import{_ as a,o as n,c as e,a0 as p}from"./chunks/framework.l1I-fhud.js";const m=JSON.parse('{"title":"tamias CLI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),i={name:"reference/cli.md"};function t(l,s,r,c,o,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="tamias-cli" tabindex="-1">tamias CLI <a class="header-anchor" href="#tamias-cli" aria-label="Permalink to &quot;tamias CLI&quot;">​</a></h1><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Package &amp; content manager — fetch, store, cache, dispense</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage: tamias [COMMAND]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commands:</span></span>
<span class="line"><span>  install          Fetch → store a package from a ref</span></span>
<span class="line"><span>  add              Install a ref and record it in \`tamias.yaml\` + \`tamias.lock\`</span></span>
<span class="line"><span>  sync             Reconcile the cwd project&#39;s dep set against the store — install what&#39;s missing or drifted. Never removes store entries: the store is global, not project-scoped; \`tamias remove\` stays the uninstall verb</span></span>
<span class="line"><span>  remove           Drop a store entry (cache untouched)</span></span>
<span class="line"><span>  list             List installed packages</span></span>
<span class="line"><span>  info             Show one package&#39;s manifest + provenance</span></span>
<span class="line"><span>  verify           Digest-check a package against its record</span></span>
<span class="line"><span>  update           Re-resolve + re-install a package from its recorded ref</span></span>
<span class="line"><span>  pin              Retarget an installed package&#39;s recorded source ref</span></span>
<span class="line"><span>  self-upgrade     Update the tamias package this binary belongs to</span></span>
<span class="line"><span>  bin              Manage a package&#39;s executable surfaces — the declared \`bins[]\` (generated \`cli\` shims + \`tools/bin/&lt;triple&gt;/\` payloads) and \`bin/\` payload files — on the bin dir (\`$TAMIAS_BIN_DIR\` → \`XDG_BIN_HOME\` → \`~/.local/bin\`)</span></span>
<span class="line"><span>  cache            Fetch-cache maintenance</span></span>
<span class="line"><span>  version          Print the tamias version</span></span>
<span class="line"><span>  manifest         Print the machine-readable capability manifest</span></span>
<span class="line"><span>  schema           Print the \`tamias.yaml\` JSON Schema</span></span>
<span class="line"><span>  gen-cli-docs     Print the CLI reference (markdown) generated from the parser</span></span>
<span class="line"><span>  completions      Print a shell completion script</span></span>
<span class="line"><span>  doctor           Diagnose the host metaservice (store, cache, registry, drivers)</span></span>
<span class="line"><span>  config           Show the effective config — YAML (\`tamias.yml\`) is the standard</span></span>
<span class="line"><span>  serve            Run the ndjson JSON-RPC service over stdio</span></span>
<span class="line"><span>  publish          Publish a package dir to a registry</span></span>
<span class="line"><span>  search           Search a registry&#39;s index</span></span>
<span class="line"><span>  bundle           Author-side packing</span></span>
<span class="line"><span>  registry         Registry operations — named sources in the config file</span></span>
<span class="line"><span>  deploy-registry  Deploy the registry Worker (Cloudflare)</span></span>
<span class="line"><span>  deploy           Deploy an installed package&#39;s service/runtime (via its provider)</span></span>
<span class="line"><span>  uninstall        Uninstall — provider teardown + drop the store entry</span></span>
<span class="line"><span>  service          Manage a per-user service unit (systemd)</span></span>
<span class="line"><span>  drivers          List discovered content drivers (\`tamias-driver-&lt;type&gt;\` on PATH + \`&lt;tamias-home&gt;/drivers/\`)</span></span>
<span class="line"><span>  driver           Provider-verb dispatch — run a driver verb beyond the lifecycle three (\`install\`/\`deploy\`/\`uninstall\`)</span></span>
<span class="line"><span>  provider         Provider packages — the declarative \`provider:\` runtime spec</span></span>
<span class="line"><span>  run              Run an installed provider service&#39;s exec in the foreground — the unit&#39;s argv + env, without systemd. \`tamias run &lt;pkg&gt; [service] [-- extra-args]\`</span></span>
<span class="line"><span>  logs             Follow a package&#39;s provider units&#39; journals — \`tamias logs &lt;pkg|unit&gt;\`. A package name resolves to all its provider units; anything else is treated as a unit base name</span></span>
<span class="line"><span>  ui               Interactive package-manager TUI (ratatui) — installed entries, registry search, provider lifecycle, manifest deps, authoring</span></span>
<span class="line"><span>  help             Print this message or the help of the given subcommand(s)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -h, --help</span></span>
<span class="line"><span>          Print help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -V, --version</span></span>
<span class="line"><span>          Print version</span></span></code></pre></div>`,2)])])}const g=a(i,[["render",t]]);export{m as __pageData,g as default};
